// Helper functions
function block(x,y,z,t){voxel(x,y,z,t)}
function box(x1,y1,z1,x2,y2,z2,t){
  for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)
  for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)
  for(let z=Math.min(z1,z2);z<=Math.max(z1,z2);z++)
    voxel(x,y,z,t)
}
function line(x1,y1,z1,x2,y2,z2,t){
  let dx=Math.abs(x2-x1),dy=Math.abs(y2-y1),dz=Math.abs(z2-z1)
  let xs=x1<x2?1:-1,ys=y1<y2?1:-1,zs=z1<z2?1:-1
  let x=x1,y=y1,z=z1
  if(dx>=dy&&dx>=dz){let s=dx;dx=0;dy/=s;dz/=s;s=1}else if(dy>=dx&&dy>=dz){let s=dy;dy=0;dx/=s;dz/=s;s=dy}else{let s=dz;dz=0;dx/=s;dy/=s;s=dz}
  while(dx<s||dy<s||dz<s){voxel(x,y,z,t);x+=dx;y+=dy;z+=dz}
  voxel(x2,y2,z2,t)
}
function ellipse(cx,cy,cz,rx,ry,rz,t){
  for(let x=Math.floor(cx-rx);x<=Math.ceil(cx+rx);x++)
  for(let y=Math.floor(cy-ry);y<=Math.ceil(cy+ry);y++)
  for(let z=Math.floor(cz-rz);z<=Math.ceil(cz+rz);z++){
    let dx=(x-cx)/rx,dy=(y-cy)/ry,dz=(z-cz)/rz
    if(dx*dx+dy*dy+dz*dz<=1)voxel(x,y,z,t)
  }
}
function circleY(cx,cy,cz,r,t){
  for(let x=Math.floor(cx-r);x<=Math.ceil(cx+r);x++)
  for(let z=Math.floor(cz-r);z<=Math.ceil(cz+r);z++){
    let dx=x-cx,dz=z-cz
    if(dx*dx+dz*dz<=r*r)voxel(x,cy,z,t)
  }
}
function circleX(cx,cy,cz,r,t){
  for(let y=Math.floor(cy-r);y<=Math.ceil(cy+r);y++)
  for(let z=Math.floor(cz-r);z<=Math.ceil(cz+r);z++){
    let dy=y-cy,dz=z-cz
    if(dy*dy+dz*dz<=r*r)voxel(cx,y,z,t)
  }
}
function circleZ(cx,cy,cz,r,t){
  for(let x=Math.floor(cx-r);x<=Math.ceil(cx+r);x++)
  for(let y=Math.floor(cy-r);y<=Math.ceil(cy+r);y++){
    let dx=x-cx,dy=y-cy
    if(dx*dx+dy*dy<=r*r)voxel(x,y,cz,t)
  }
}
function cylinderX(cx,cy,cz,r1,r2,len,t){
  for(let x=0;x<len;x++){
    let t2=x/(len-1)
    let r=r1+(r2-r1)*t2
    circleX(cx+x,cy,cz,Math.round(r),t)
  }
}
function cylinderZ(cx,cy,cz,r1,r2,len,t){
  for(let z=0;z<len;z++){
    let t2=z/(len-1)
    let r=r1+(r2-r1)*t2
    circleX(cx,cy,cz+z,Math.round(r),t)
  }
}
function cylinderY(cx,cy,cz,r1,r2,len,t){
  for(let y=0;y<len;y++){
    let t2=y/(len-1)
    let r=r1+(r2-r1)*t2
    circleY(cx,cy+y,cz,Math.round(r),t)
  }
}
function wedge(x1,y1,z1,x2,y2,z2,t){
  for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)
  for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)
  for(let z=Math.min(z1,z2);z<=Math.max(z1,z2);z++){
    let fx=(x-Math.min(x1,x2))/(Math.abs(x2-x1)+1)
    let fy=(y-Math.min(y1,y2))/(Math.abs(y2-y1)+1)
    if(fx+fy<=1)voxel(x,y,z,t)
  }
}

