// Function to build a wheel with spokes
function buildWheel(cx,cy,cz,radius,thickness,color){
  // Outer rim
  for(let i=0;i<thickness;i++){
    let z=cz-i+(thickness-1)/2
    circleX(cx,cy,z,radius,color)
  }
  // Hub
  for(let i=0;i<thickness;i++){
    let z=cz-i+(thickness-1)/2
    circleX(cx,cy,z,2,'gold_block')
  }
  // Spokes
  for(let s=0;s<6;s++){
    let angle=s*Math.PI/3
    for(let r=2;r<radius;r++){
      let dx=Math.round(r*Math.cos(angle))
      let dy=Math.round(r*Math.sin(angle))
      for(let i=0;i<thickness;i++){
        let z=cz-i+(thickness-1)/2
        voxel(cx+dx,cy+dy,z,color)
      }
    }
  }
}

// Function to build driving wheels with rods
function buildDriverWheel(cx,cy,cz,radius,color){
  // Outer rim - thick
  for(let z=-3;z<=3;z++){
    circleX(cx,cy,cz+z,radius,'gray_wool')
  }
  // Inner rim detail
  for(let z=-2;z<=2;z++){
    circleX(cx,cy,cz+z,Math.max(0,radius-1),'iron_block')
  }
  // Hub
  for(let z=-3;z<=3;z++){
    circleX(cx,cy,cz+z,3,'gold_block')
  }
  // Spokes
  for(let s=0;s<8;s++){
    let angle=s*Math.PI/4
    for(let r=3;r<radius-1;r++){
      let dx=Math.round(r*Math.cos(angle))
      let dy=Math.round(r*Math.sin(angle))
      for(let z=-3;z<=3;z++){
        voxel(cx+dx,cy+dy,cz+z,'gray_wool')
      }
    }
  }
}

// Connecting rod
function buildRod(x1,y1,z1,x2,y2,z2){
  let dx=x2-x1,dy=y2-y1,dz=z2-z1
  let len=Math.sqrt(dx*dx+dy*dy+dz*dz)
  let steps=Math.ceil(len/2)
  for(let i=0;i<=steps;i++){
    let t=i/steps
    let x=Math.round(x1+dx*t)
    let y=Math.round(y1+dy*t)
    let z=Math.round(z1+dz*t)
    box(x-1,y-1,z,x+1,y+1,z,'iron_block')
    // Add a joint circle
    if(i===0||i===steps){
      circleY(x,y,z,3,'gold_block')
    }
  }
}

