// === PASSENGER CARS ===
function buildPassengerCar(startX,color1,color2){
  const length=25
  const width=6
  const height=10
  const baseY=BOILER_Y-8

  // Floor
  for(let x=startX;x<startX+length;x++){
    for(let z=-width;z<=width;z++){
      box(x,baseY,CZ+z,x,baseY,CZ+z,color2)
    }
  }

  // Walls
  for(let x=startX;x<startX+length;x++){
    for(let y=baseY+1;y<baseY+height;y++){
      for(let z=-width;z<=width;z++){
        let isEdge=Math.abs(z)===width
        if(isEdge){
          block(x,y,CZ+z,color1)
        } else {
          block(x,y,CZ+z,color1)
        }
      }
    }
  }

  // Windows
  for(let x=startX+2;x<startX+length-2;x+=3){
    for(let z=-width;z<=width;z++){
      if(Math.abs(z)===width){
        block(x,baseY+4,CZ+z,'glass')
        block(x,baseY+5,CZ+z,'glass')
        block(x,baseY+6,CZ+z,'glass')
      }
    }
  }

  // Roof
  for(let x=startX;x<startX+length;x++){
    for(let z=-width-1;z<=width+1;z++){
      block(x,baseY+height,CZ+z,color2)
    }
  }

  // Roof overhang
  for(let x=startX;x<startX+length;x++){
    block(x,baseY+height+1,CZ-(width+1),x,baseY+height+1,CZ-(width+1),color2)
    block(x,baseY+height+1,CZ+(width+1),x,baseY+height+1,CZ+(width+1),color2)
  }

  // Wheels
  for(let x=startX+3;x<startX+length-3;x+=3){
    circleX(x,baseY-2,CZ-width,2,'gray_wool')
    circleX(x,baseY-2,CZ+width,2,'gray_wool')
  }

  return startX+length
}

